import{_ as t,c as p,o as s,ah as o,ao as i,ap as a}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"允许自己悲伤——你的眼泪，祂都收在瓶子里","description":"为宠物离世而哭，不是信心不足。诗篇说神把我们的眼泪收在瓶子里，记在册上。","frontmatter":{"title":"允许自己悲伤——你的眼泪，祂都收在瓶子里","description":"为宠物离世而哭，不是信心不足。诗篇说神把我们的眼泪收在瓶子里，记在册上。"},"headers":[],"relativePath":"zh/pets-in-heaven/permission-to-grieve.md","filePath":"zh/pets-in-heaven/permission-to-grieve.md"}'),n={name:"zh/pets-in-heaven/permission-to-grieve.md"};function l(c,e,r,h,m,d){return s(),p("div",null,[...e[0]||(e[0]=[o('<div class="pl-quote"><p>「都过了几个月了，我还在哭。是不是我不够坚强？是不是我信心太小？」</p><p class="pl-quote-soft">圣经从来没有把眼泪当成失败的证据。刚好相反。</p></div><section class="pl-section"><h2>一、神把眼泪收在瓶子里</h2><blockquote><p><strong>诗篇 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>大卫在极深的痛苦里写下这句话。他求神把他的眼泪装在瓶子里，记在册上——在古代，瓶子里的泪是极珍贵的收藏，是「这个人为这件事哭过」的凭据。</p><p>这意味着：<strong>你的眼泪不是流掉就消失的东西。</strong>没有一滴被浪费。为它流的每一滴，神都收着、都记着。</p><p>当你觉得「我是不是哭太多了」，请记得：在神那里，那不是杂讯，那是纪录。</p></section><section class="pl-section"><h2>二、神靠近伤心的人，而不是责备他们</h2><blockquote><p><strong>诗篇 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>诗篇 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>注意动词：祂<em>靠近</em>、祂<em>医治</em>、祂<em>缠裹</em>。神对伤心的人所做的第一件事，不是要求他振作，而是走过去。</p><p>耶稣也说过一句很短的话：</p><blockquote><p><strong>马太福音 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>「哀恸的人有福了。」悲伤的人不是被责备，而是被宣告有福——因为安慰会来。不是「你应该高兴起来」，而是「你会得安慰」。</p></section><section class="pl-section"><h2>三、悲伤不是爱的反面，是爱还在继续</h2><p>我们不会为不曾爱过的东西哭。你今天会这么痛，正是因为你们之间真的有过爱。</p><p>神造我们，本来就是会为失去而哭泣的存在。耶稣自己在拉撒路的坟前也哭了（约翰福音 11:35）——祂明知几分钟后就要叫他从死里复活，祂还是哭了。</p><p>所以你不必为眼泪感到抱歉。你不是信心不够，你只是在爱里受了伤。</p><p class="pl-quote-soft">如果你愿意，可以这样祷告：</p></section><div class="pl-quote"><p>「主啊，祢知道我哭了多少次。<br>谢谢祢没有催我快点好起来，反而把每一滴眼泪收在瓶子里。<br>求祢靠近我，如同祢靠近每一个心碎的人；<br>求祢医治我，也替我照顾我想念的那一个。<br>今天我不想变强，只想被祢抱住。阿们。」</p></div><section class="pl-section"><h2>四件现在可以为自己做的事</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>不要在情绪最强时做决定</h3><p>悲伤的浪会过去。在最痛的那一刻，只要活过那五分钟就够了——不要处理任何事情。</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>先照顾身体</h3><p>喝水、吃点东西、睡一下。哀伤会消耗身体，而身体饿的时候，心会更痛。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>把它写进一本笔记</h3><p>不必写得漂亮。写下一个细节：它怎么叫你起床、你最喜欢它哪个表情。让想念有地方放。</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>找一个真的懂的人</h3><p>不是每个人都懂为动物哭，但有些人懂。如果找不到，写下来也可以——神读得到。</p></div></div></section><section class="pl-section"><h2>那一天会来</h2><p>启示录应许，有一天神要亲自擦去我们一切的眼泪，不再有死亡、悲哀、哭号、疼痛（启示录 21:4）。那一天，你会发现你为它流的每一滴眼泪，都被那位良善的神记得、也被那位良善的神回应。</p><p>在那之前，允许自己悲伤。那是你还能爱它的方式。</p><p><a href="/zh/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 回到第一篇：<a href="/zh/pets-in-heaven/will-i-see-my-pet-again">它会在那里吗？</a></p></section><div class="pl-cta"><h2>今天，只要写一句话就好。</h2><p>PetLoss 里有引导式日记与 SOS 陪伴，在你最沉重的时刻给你落地的话语。无需帐号、不上传、完全离线。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下载</a></div><div class="pl-bible"><h3>让圣经的话继续陪你</h3><p>文中引用的经文都出自圣经。用《彩虹圣经》随时阅读神的话、设置每日经文小组件，在想念它的日子里仍有一盏灯。</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Rainbow Bible 圣经小组件显示 2 Timothy 2:13" loading="lazy"><figcaption>每日经文放在主屏幕</figcaption></figure><figure><img src="'+a+'" alt="Rainbow Bible App 的「天堂里的毛孩」主题，显示 Matthew 10:29-31" loading="lazy"><figcaption>切换到「天堂里的毛孩」主题读经</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 获取《彩虹圣经》</a></div>',9)])])}const g=t(n,[["render",l]]);export{v as __pageData,g as default};
